def enrich_meta_campaign_summary(frame, aggregate_rows, filter_rows, level):
    field_pairs = {
        "campaign": (("base_campaign_name", "campaign_name"),),
        "adset": (
            ("base_campaign_name", "campaign_name"),
            ("adset_name", "adset_name"),
        ),
