        str(row.get("campaign_name"))
        for row in aggregate_rows + filter_rows
        if row.get("campaign_name")
    }

    def canonical_campaign(value):
        value = str(value)
        if value in known_campaigns:
            return value
        matches = sorted(
            (name for name in known_campaigns if value.startswith(f"{name}_")),
            key=len,
            reverse=True,
        )
        if not matches or len(matches) > 1 and len(matches[0]) == len(matches[1]):
            return None
        return matches[0]

    def record_key(record, summary_side):
        values = []
        for summary_field, meta_field in field_pairs:
            field = summary_field if summary_side else meta_field
            value = record.get(field, "")
            if summary_side and meta_field == "campaign_name":
                value = canonical_campaign(value)
                if value is None:
                    return None
            values.append(str(value))
        return tuple(values)

    def record_id(record):
        return str(record.get(id_field) or "")

    def index_rows(rows):
        by_key = {}
        by_id = {}
        for row in rows:
            by_key.setdefault(record_key(row, False), []).append(row)
            if record_id(row):
                by_id.setdefault(record_id(row), []).append(row)
        return by_key, by_id

    def source_value(matches, by_id, stable_id, value_for_row, unavailable):
        rows = by_id.get(stable_id, []) if stable_id else []
        if not rows and len(matches) == 1 and not record_id(matches[0]):
            rows = matches
        values = [value_for_row(row) for row in rows]
        if not values or any(value != values[0] for value in values[1:]):
            return unavailable
        return values[0]

    native_by_key, native_by_id = index_rows(aggregate_rows)
    budget_by_key, budget_by_id = index_rows(filter_rows)

